mapper.select:
SELECT id, username, display_name, password_hash, platform_role, status, email, sso_issuer, sso_subject,
       avatar_url, gender, phone, created_at
FROM users WHERE lower(username) = #{username}

SELECT id, username, display_name, password_hash, platform_role, status, email, sso_issuer, sso_subject,
       avatar_url, gender, phone, created_at
FROM users WHERE email IS NOT NULL AND lower(email) = #{email}

SELECT id, username, display_name, password_hash, platform_role, status, email, sso_issuer, sso_subject,
       avatar_url, gender, phone, created_at
FROM users WHERE sso_issuer = #{issuer} AND sso_subject = #{subject}

SELECT id, username, display_name, password_hash, platform_role, status, email, sso_issuer, sso_subject,
       avatar_url, gender, phone, created_at
FROM users WHERE id = #{id}

mapper.update:
UPDATE organization_memberships
SET role = COALESCE(#{role}, role), status = COALESCE(#{status}, status), updated_at = now()
WHERE organization_id = #{organizationId} AND id = #{id}

UPDATE organization_invites
SET accepted_at = now(), accepted_by = #{acceptedBy}
WHERE id = #{id}
  AND accepted_at IS NULL
  AND expires_at > now()
